{
  "county_id": "HVA07",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The portfolio picks timed-pathways for Kanta-Häme wellbeing services county at EUR 253,436 a year, with a model scenario of about 8 deaths postponed a year (range 1.2-16) and the action stayed in 85% of sensitivity runs, while the county waits 56 per 10 000 inhabitants for specialised care against 36 nationally.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "Cervical screening participation in Kanta-Häme wellbeing services county is 70.6% against the 80% target, and the portfolio selects self-sampling at EUR 101,374 a year with an expected gain of 1.5-4.5 percentage points, closing about 32% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in Kanta-Häme wellbeing services county is 75.9% against the 80% target, and the portfolio selects screening-reminders at EUR 67,583 a year with an expected gain of 1.5-4.07 percentage points, closing about 74% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support that these actions will reduce cancer mortality in Kanta-Häme wellbeing services county: the timed-pathways estimate is a model scenario under stated assumptions, Danish pathway evidence is before/after without a control group, the Finnish self-sampling gain is about 3 points and far smaller than the international pooled estimate, and no Finnish effect size exists for colorectal reminders."
}

